let data = msg.payload;

// Validación básica de campos biomédicos
if (!data || !data.paciente_id || data.bpm === undefined || data.spo2 === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        error: "Bad Request",
        message: "Faltan campos obligatorios: paciente_id, bpm, spo2"
    };
    return msg;
}

// Estructurar registro y guardar en contexto de flujo
data.servidor_timestamp = new Date().toISOString();
flow.set("ultimo_paciente_data", data);

// Respuesta al cliente HTTP (ESP32 o frontend)
msg.statusCode = 201;
msg.payload = {
    status: "success",
    message: "Constantes vitales registradas satisfactoriamente",
    paciente: data.paciente_id,
    timestamp: data.servidor_timestamp
};

return msg;

let ultimo = flow.get("ultimo_paciente_data");

if (!ultimo) {
    msg.statusCode = 404;
    msg.payload = {
        error: "Not Found",
        message: "Aún no se han recibido registros de telemetría médica"
    };
} else {
    msg.statusCode = 200;
    msg.payload = {
        status: "ok",
        data: ultimo
    };
}

return msg;
